/**
 * An agent run's steps, each with its status (`design/components/plan.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/plan.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  claimSlot,
  classes,
  createDerived,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/plan.module.css'

export type PlanStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped'

export interface PlanStep {
  id: string
  title: string
  description?: string
  status: PlanStatus
}

export interface PlanMessages {
  status: Record<PlanStatus, string>
}

export interface PlanProps {
  /**
   * The list's accessible name, such as "Plan for this run" rather than "Plan".
   */
  label: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PlanMessages
  /**
   * The steps in reading order. Plan never sorts them, and an empty list renders nothing.
   */
  steps: PlanStep[]
}

/** An agent run's steps, each with its status. */
export default function Plan(given: PlanProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({
        status: {
          pending: 'Pending',
          running: 'Running',
          done: 'Done',
          error: 'Failed',
          skipped: 'Skipped',
        },
      }))(),
    } as Defaults<PlanProps, 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const currentId = createDerived(() => props.steps.find((step) => step.status === 'running')?.id)
    const announcement = createDerived(() =>
      ((front: PlanStep | undefined) =>
        front === undefined ? '' : `${front.title}, ${props.messages.status[front.status]}`)(
        props.steps.find((step) => step.status === 'running') ??
          props.steps.find((step) => step.status === 'error') ??
          [...props.steps]
            .reverse()
            .find((step) => step.status === 'done' || step.status === 'skipped'),
      ),
    )
    return (
      <>
        {props.steps.length > 0 ? (
          <div class={styles.root} data-member="plan">
            {/* list */}
            <ol class={styles.list} role="list" aria-label={props.label}>
              <Each of={props.steps} by={(step) => step.id} renew>
                {(step) => (
                  <li
                    class={styles.step}
                    data-status={step.status}
                    aria-current={step.id === currentId.value ? 'step' : undefined}
                    aria-busy={step.status === 'running' ? true : undefined}
                  >
                    {/* mark */}
                    <span class={styles.mark} aria-hidden="true">
                      {step.status === 'running' ? (
                        <span class={classes(styles.glyph, styles.spinning)}>
                          <Icon name="loading" size="sm" />
                        </span>
                      ) : step.status === 'done' ? (
                        <span class={styles.glyph}>
                          <Icon name="success" size="sm" />
                        </span>
                      ) : step.status === 'error' ? (
                        <span class={styles.glyph}>
                          <Icon name="error" size="sm" />
                        </span>
                      ) : step.status === 'skipped' ? (
                        <span class={styles.glyph}>
                          <Icon name="remove" size="sm" />
                        </span>
                      ) : (
                        <span class={styles.glyph}>
                          <Icon name="time" size="sm" />
                        </span>
                      )}
                    </span>
                    {/* copy */}
                    <span class={styles.copy}>
                      {/* title */}
                      <span class={styles.title}>{step.title}</span>
                      <span class={styles.reader}>{`, ${props.messages.status[step.status]}`}</span>
                      {step.description !== undefined ? (
                        <span class={styles.description}>{step.description}</span>
                      ) : null}
                    </span>
                  </li>
                )}
              </Each>
            </ol>
            {/* line */}
            <p class={styles.line} role="status">
              {announcement.value}
            </p>
          </div>
        ) : null}
      </>
    )
  })
}
